select public.send_message('95000000-0000-0000-0000-000000000012',current_setting('test.group')::uuid,'Group message');
select public.chat_action('forward',jsonb_build_object('message','95000000-0000-0000-0000-000000000011','destination',current_setting('test.group'),'id','95000000-0000-0000-0000-000000000013'));
